// add inertia matrix to dense destination matrix
void mj_addMDense(const mjModel* m, mjData* d, mjtNum* dst) {
  int nv = m->nv;

  for (int i = 0; i < nv; i++) {
    int adr = m->dof_Madr[i];
    int j = i;
    while (j >= 0) {
      // add
      dst[i*nv+j] += d->qM[adr];
