// prism center function
static void mjc_prism_center(mjtNum res[3], const mjCCDObj* obj) {
  // compute mean
  mju_zero3(res);
  for (int i=0; i < 6; i++) {
    mju_addTo3(res, obj->prism[i]);
  }
  mju_scl3(res, res, 1.0/6.0);
}



