        mj_jac(m, d, jac1, NULL, pos1, b1);
        mj_jac(m, d, jac2, NULL, pos2, b2);
        mju_sub(jacdif, jac2, jac1, 3*nv);

        // apply chain rule to compute edge Jacobian
        mju_mulMatTVec(J + (ebase+e)*nv, jacdif, vec, 3, nv);
      }
    }
  }

  mj_freeStack(d);
}

